/* @lc app=leetcode id=2258 lang=kotlin */
class Solution { fun maximumMinutes(grid: Array<IntArray>): Int = (grid.size to grid[0].size).let { (R, C) -> ({ start: List<Triple<Int, Int, Int>>, isFire: Boolean, fire: Array<IntArray>? -> Array(R) { IntArray(C) { 2000000000 } }.apply { java.util.ArrayDeque<Triple<Int, Int, Int>>().let { q -> start.forEach { (r, c, t) -> if (this[r][c] > t) this[r][c] = t.also { q.add(Triple(r, c, t)) } }.let { while (q.isNotEmpty()) q.poll().let { (r, c, t) -> listOf(0 to 1, 0 to -1, 1 to 0, -1 to 0).forEach { (dr, dc) -> (r + dr to c + dc).let { (nr, nc) -> if (nr in 0 until R && nc in 0 until C && (if (isFire) grid[nr][nc] != 2 else grid[nr][nc] == 0) && this[nr][nc] > t + 1 && (fire == null || (if (nr == R - 1 && nc == C - 1) fire[nr][nc] >= t + 1 else fire[nr][nc] > t + 1))) this[nr][nc] = (t + 1).also { q.add(Triple(nr, nc, t + 1)) } } } } } } } }).let { bfs -> bfs(grid.indices.flatMap { r -> grid[0].indices.filter { grid[r][c] == 1 }.map { c -> Triple(r, c, 0) } }, true, null).let { fire -> generateSequence(Triple(0, 1000000000, -1)) { (l, r, res) -> if (l > r) null else ((l + r) / 2).let { mid -> if (bfs(listOf(Triple(0, 0, mid)), false, fire)[R - 1][C - 1] < 2000000000) Triple(mid + 1, r, mid) else Triple(l, mid - 1, res) } }.last().third } } } }